// Extraer datos recibidos desde la Web App Diata
const body = $input.item.json.body || $input.item.json;
const recipes = body.recipes || [];
const lockedMeals = body.locked_meals || [];
const familyRules = body.family_rules || '';
const customPrompt = body.prompt || '';

const days = [
  { day_index: 1, day_name: "Lunes" },
  { day_index: 2, day_name: "Martes" },
  { day_index: 3, day_name: "Miércoles" },
  { day_index: 4, day_name: "Jueves" },
  { day_index: 5, day_name: "Viernes" },
  { day_index: 6, day_name: "Sábado" },
  { day_index: 7, day_name: "Domingo" }
];

// Colección de IDs asignados para evitar repeticiones
const usedRecipeIds = new Set();

// 1. Registrar recetas bloqueadas
lockedMeals.forEach(lm => {
  if (lm.lunch_locked) {
    const r = recipes.find(rec => rec.title.toLowerCase() === lm.lunch_locked.toLowerCase());
    if (r) usedRecipeIds.add(r.id);
  }
  if (lm.dinner_locked) {
    const r = recipes.find(rec => rec.title.toLowerCase() === lm.dinner_locked.toLowerCase());
    if (r) usedRecipeIds.add(r.id);
  }
});

// Separar piscinas de comida y cena
const lunchPool = recipes.filter(r => !r.meal_target || r.meal_target === 'lunch' || r.meal_target === 'both');
const dinnerPool = recipes.filter(r => !r.meal_target || r.meal_target === 'dinner' || r.meal_target === 'both');

function pickUnique(pool) {
  let candidates = pool.filter(r => !usedRecipeIds.has(r.id));
  if (candidates.length === 0) candidates = recipes.filter(r => !usedRecipeIds.has(r.id));
  if (candidates.length === 0) candidates = pool.length > 0 ? pool : recipes;

  if (candidates.length === 0) return { id: null, title: 'Sin planificar' };

  const picked = candidates[Math.floor(Math.random() * candidates.length)];
  if (picked && picked.id) usedRecipeIds.add(picked.id);
  return picked;
}

// Construir menú semanal único sin duplicados
const generatedMenu = days.map(d => {
  const locked = lockedMeals.find(lm => lm.day_index === d.day_index) || {};

  let lunchObj;
  if (locked.lunch_locked) {
    const r = recipes.find(rec => rec.title.toLowerCase() === locked.lunch_locked.toLowerCase());
    lunchObj = { recipe_id: r ? r.id : null, title: locked.lunch_locked, completed: false, locked: true };
  } else {
    const r = pickUnique(lunchPool);
    lunchObj = { recipe_id: r.id, title: r.title, completed: false, locked: false };
  }

  let dinnerObj;
  if (locked.dinner_locked) {
    const r = recipes.find(rec => rec.title.toLowerCase() === locked.dinner_locked.toLowerCase());
    dinnerObj = { recipe_id: r ? r.id : null, title: locked.dinner_locked, completed: false, locked: true };
  } else {
    const r = pickUnique(dinnerPool);
    dinnerObj = { recipe_id: r.id, title: r.title, completed: false, locked: false };
  }

  return {
    day_index: d.day_index,
    day_name: d.day_name,
    lunch: lunchObj,
    dinner: dinnerObj
  };
});

return {
  json: {
    status: "success",
    engine: "n8n_diata_smart_rules_v1",
    family_rules_applied: familyRules,
    custom_prompt: customPrompt,
    generated_menu: generatedMenu
  }
};
